story.append(P("Table 3: Retrieval settings (real gpt-oss-20b, 24 questions, no load; first-token time includes governor queueing, see section 3)", TH)); story.append(table(tbl("Table 3"), [W*.2, W*.05, W*.07, W*.09, W*.07, W*.09, W*.07, W*.18, W*.18]))
