def frame_doc():
    d = BaseDocTemplate(str(ROOT / "REPORT.pdf"), pagesize=A4, leftMargin=10*mm, rightMargin=10*mm, topMargin=8*mm, bottomMargin=8*mm,
                        title="The Relay - write-up", author="")
    fr = Frame(d.leftMargin, d.bottomMargin, d.width, d.height, id="f", leftPadding=0, rightPadding=0, topPadding=0, bottomPadding=0)
    d.addPageTemplates([PageTemplate(id="p", frames=[fr])]); return d
frame_doc().build(story)
